1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Rejects a create-owner request whose city already contains {@link #CITY_CAPACITY} or more owners.
12	 * Runs before the owner is built and saved. Cities are matched case-insensitively after trimming and
13	 * collapsing runs of whitespace to a single space. A city at capacity is rejected via
14	 * {@link CityAtCapacityException}, which the global handler turns into a 409.
15	 */
16	public class RejectCityAtCapacity {
17	
18	    /** Maximum number of owners allowed per city; the request is rejected once this many already exist. */
19	    static final int CITY_CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws CityAtCapacityException {
23	        String city = normalize(request.getCity());
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (city.equals(normalize(existing.getCity()))) {
27	                count++;
28	            }
29	        }
30	        if (count >= CITY_CAPACITY) {
31	            throw new CityAtCapacityException(request.getCity(), CITY_CAPACITY);
32	        }
33	    }
34	
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
40	    }
41	}
