16	
17	    /** The warning is raised once strictly more than this many owners already exist for the day. */
18	    static final int BULK_SIGNUP_THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        int count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (owner.getRegistrationDate() != null
24	                    && owner.getRegistrationDate().equals(existing.getRegistrationDate())) {
25	                count++;
26	            }
27	        }
28	        owner.setBulkSignupWarning(count > BULK_SIGNUP_THRESHOLD);
29	    }
30	}
